<p class="by" class:on={draw > 0.05}>Created by</p>
<svg class="logo" class:lit class:reduced viewBox="280 120 2560 1980" role="img" aria-label="Hodag Digital">
  <!-- the blood on the fangs and letters, which keeps stretching a little, as if it's still running -->
  <g class="blood" style:opacity={fill}>
    {#each BLOOD as d, i (i)}<path {d} style:--k={i} />{/each}
  </g>
  <!-- HODAG: filled as it finishes drawing -->
  <path class="fill" d={HODAG} fill-rule="evenodd" clip-rule="evenodd" style:fill-opacity={fill} />
  <!-- ...and its outline, drawn in with the scroll -->
  <path class="line" d={HODAG} pathLength="1" style:stroke-dashoffset={1 - draw} style:opacity={draw > 0.001 ? 1 - fill * 0.85 : 0} />

  <!-- DIGITAL, in the mouth -->
  <g class="digital">
    <text class="ghost c" x="1560" y="1762" text-anchor="middle" textLength="1380" lengthAdjust="spacingAndGlyphs">DIGITAL</text>
    <text class="ghost m" x="1560" y="1762" text-anchor="middle" textLength="1380" lengthAdjust="spacingAndGlyphs">DIGITAL</text>
    <text class="word" x="1560" y="1762" text-anchor="middle" textLength="1380" lengthAdjust="spacingAndGlyphs">DIGITAL</text>
  </g>

  <!-- the artwork's drops, falling off the drips onto DIGITAL: form on the tip, fall, splat, run down the letter -->
  {#if lit && !reduced}
    {#each DROPS as d, i (i)}
      <g
        class="drop"
        style:--from="{d.tip - d.top}px"
        style:--d="{LAND - d.top - 18}px"
        style:animation-duration="{d.dur}s"
        style:animation-delay="{d.delay}s"
      >
        <path class="bead" d={d.d} />
        <ellipse class="splat" cx={d.x} cy={LAND + 4} rx="34" ry="11" />
        <rect class="run" x={d.x - 6} y={LAND} width="12" height="95" rx="6" />
      </g>
    {/each}
  {/if}
</svg>

<style>
  .by {
    margin: 0 0 4px;
    text-align: center;
    font-size: 11px;
    font-weight: 600;
    letter-spacing: 0.22em;
    text-transform: uppercase;
    color: rgba(255, 255, 255, 0.55);
    opacity: 0;
    transform: translateY(6px);
    transition:
      opacity 500ms ease,
      transform 600ms cubic-bezier(0.2, 1, 0.3, 1);
  }
  .by.on {
    opacity: 1;
    transform: none;
  }
  .logo {
    display: block;
    width: 100%;
    height: auto;
    overflow: visible;
  }
  .fill {
    fill: #fff;
  }
  .line {
    fill: none;
    stroke: #fff;
    stroke-width: 7;
    stroke-linejoin: round;
    stroke-dasharray: 1;
  }
  .blood path {
    fill: #e10b0b;
    transform-box: fill-box;
    transform-origin: 50% 0;
  }
  .lit .blood path {
    animation: ooze 3.2s ease-in-out calc(var(--k) * -0.37s) infinite;
  }
  @keyframes ooze {
    0%,
    100% {
      transform: scaleY(1);
    }
    50% {
      transform: scaleY(1.06);
    }
  }
  /* DIGITAL: a pixel face, popping in with a quick RGB glitch */
  .digital text {
    font-family: 'Silkscreen', monospace;
    font-weight: 700;
    font-size: 320px;
  }
  .digital {
    transform-box: fill-box;
    transform-origin: 50% 60%;
    opacity: 0;
    transform: scale(0.55);
    transition:
      opacity 160ms ease-in,
      transform 200ms ease-in;
  }
  .lit .digital {
    opacity: 1;
    transform: none;
    transition:
      opacity 120ms linear 180ms,
      transform 560ms cubic-bezier(0.2, 1.6, 0.4, 1) 180ms;
  }
  .word {
    fill: #fff;
  }
  .ghost {
    opacity: 0;
  }
  .ghost.c {
    fill: #2ee6ff;
  }
  .ghost.m {
    fill: #ff2bd6;
  }
  .lit .ghost.c {
    animation: glitch-c 520ms steps(1) 200ms;
  }
  .lit .ghost.m {
    animation: glitch-m 520ms steps(1) 200ms;
  }
  @keyframes glitch-c {
    0% { opacity: 0.85; transform: translate(-22px, 6px); }
    20% { opacity: 0.85; transform: translate(14px, -8px); }
    40% { opacity: 0.7; transform: translate(-8px, 0); }
    60% { opacity: 0.6; transform: translate(20px, 4px); }
    80% { opacity: 0.4; transform: translate(-4px, 0); }
    100% { opacity: 0; transform: none; }
  }
  @keyframes glitch-m {
    0% { opacity: 0.85; transform: translate(20px, -6px); }
    20% { opacity: 0.85; transform: translate(-16px, 8px); }
    40% { opacity: 0.7; transform: translate(10px, 0); }
    60% { opacity: 0.6; transform: translate(-18px, -4px); }
    80% { opacity: 0.4; transform: translate(4px, 0); }
    100% { opacity: 0; transform: none; }
  }
  /* a drop: grows on the drip tip, falls (gathering speed), splats on DIGITAL and runs down the letter */
  .drop {
    animation-name: none;
  }
  .drop .bead {
    fill: #e10b0b;
  }
  .drop .splat,
  .drop .run {
    fill: #c20808;
  }
  .drop .bead,
  .drop .splat,
  .drop .run {
    animation-duration: inherit;
    animation-delay: inherit;
    animation-iteration-count: infinite;
    animation-fill-mode: both;
  }
  .drop .bead {
    transform-box: fill-box;
    transform-origin: 50% 0;
    animation-name: bead;
  }
  .drop .splat {
    transform-box: fill-box;
    transform-origin: 50% 50%;
    animation-name: splat;
  }
  .drop .run {
    transform-box: fill-box;
    transform-origin: 50% 0;
    animation-name: run;
  }
  .drop {
    animation-duration: var(--dur, 3s);
  }
  @keyframes bead {
    0% { opacity: 0; transform: translateY(var(--from)) scale(0.2); animation-timing-function: ease-out; }
    16% { opacity: 1; transform: translateY(var(--from)) scale(1, 1.1); animation-timing-function: cubic-bezier(0.55, 0, 1, 0.45); }
    58% { opacity: 1; transform: translateY(var(--d)) scale(0.85, 1.25); }
    60% { opacity: 0; transform: translateY(var(--d)) scale(1.6, 0.4); }
    100% { opacity: 0; transform: translateY(var(--d)) scale(1.6, 0.4); }
  }
  @keyframes splat {
    0%, 57% { opacity: 0; transform: scale(0.2, 0.4); }
    61% { opacity: 1; transform: scale(1.25, 1); }
    70% { opacity: 1; transform: scale(1, 1); }
    100% { opacity: 0; transform: scale(1.05, 0.9); }
  }
  @keyframes run {
    0%, 59% { opacity: 0; transform: scaleY(0); }
    62% { opacity: 1; transform: scaleY(0.15); }
    92% { opacity: 0.9; transform: scaleY(1); }
    100% { opacity: 0; transform: scaleY(1); }
  }
  .reduced .blood path {
    animation: none !important;
  }
</style>
